import type { Character } from "@build-character/shared";
import { portraitSrc } from "../components/Portrait";
// Generated by vite.config.ts from data/characters.json (names + portraits only).
import reelRosterJson from "./reel-roster.generated.json";

/** Just what the roll reel's filler faces need. */
export type ReelCharacter = Pick<Character, "id" | "displayName" | "portrait">;

export const ROSTER: ReelCharacter[] = reelRosterJson as ReelCharacter[];

/** Faces downloaded up front: one reel's worth, shared by both reels. */
const FIRST_BATCH = 24;
/** Wait for the spin to finish before topping up, so new downloads don't
 * compete with the rolled character's portrait. */
const TOP_UP_DELAY_MS = 2600;
/** New faces mixed in per spin; the rest are reused from the warm pool. */
const NEW_PER_SPIN = 6;
/** Cap on kept faces so memory stays small. */
const MAX_WARM = 120;

/**
 * Faces already downloaded and decoded. The reel scrolls past fillers too fast
 * to study them, so reusing these (plus a few new ones each spin) keeps the
 * reel full of real portraits without re-downloading dozens of images per roll.
 */
const warm: { c: ReelCharacter; img: HTMLImageElement }[] = [];
const warmIds = new Set<string>();
let loading = 0;
let topUpTimer: ReturnType<typeof setTimeout> | 0 = 0;

function randomPick<T>(pool: T[]): T {
  return pool[Math.floor(Math.random() * pool.length)]!;
}

function whenIdle(fn: () => void) {
  const ric = (window as Window & { requestIdleCallback?: (cb: () => void) => number }).requestIdleCallback;
  if (ric) ric(fn);
  else setTimeout(fn, 200);
}

function warmUp(count: number) {
  if (typeof window === "undefined" || ROSTER.length === 0) return;
  whenIdle(() => {
    for (let n = 0, tries = 0; n < count && tries < count * 4; tries++) {
      const c = randomPick(ROSTER);
      if (warmIds.has(c.id)) continue;
      warmIds.add(c.id);
      n++;
      loading++;
      const img = new Image();
      img.decoding = "async";
      img.src = portraitSrc(c);
      img
        .decode()
        .then(() => {
          warm.push({ c, img });
          if (warm.length > MAX_WARM) warmIds.delete(warm.shift()!.c.id);
        })
        .catch(() => warmIds.delete(c.id))
        .finally(() => { loading--; });
    }
  });
}

/** Start downloading the first reel faces (call once the page has loaded). */
export function prepareReelFaces() {
  if (warm.length + loading === 0) warmUp(FIRST_BATCH);
}

export function pickSpinCharacters(
  count: number,
  excludeIds: Set<string>,
): ReelCharacter[] {
  const pool = ROSTER.filter((c) => !excludeIds.has(c.id));
  if (pool.length === 0) return ROSTER.slice(0, count);
  const ready = warm.map((w) => w.c).filter((c) => !excludeIds.has(c.id));
  const out: ReelCharacter[] = [];
  // Mostly faces that are already decoded, in random order...
  for (let i = ready.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [ready[i], ready[j]] = [ready[j]!, ready[i]!];
  }
  out.push(...ready.slice(0, count));
  // ...topped up with random ones if the pool is still filling.
  while (out.length < count) out.push(randomPick(pool));
  // Add a few new faces for next time, once this spin is over.
  if (!topUpTimer) {
    topUpTimer = setTimeout(() => {
      topUpTimer = 0;
      warmUp(Math.max(NEW_PER_SPIN, FIRST_BATCH - warm.length - loading));
    }, TOP_UP_DELAY_MS);
  }
  return out;
}
